do $$
declare tenant uuid:=gen_random_uuid();other_tenant uuid:=gen_random_uuid();admin_user uuid:=gen_random_uuid();manager_user uuid:=gen_random_uuid();school_user uuid:=gen_random_uuid();pending_user uuid:=gen_random_uuid();school uuid:=gen_random_uuid();person uuid:=gen_random_uuid();guardian uuid:=gen_random_uuid();ev uuid:=gen_random_uuid();sport uuid:=gen_random_uuid();cat uuid:=gen_random_uuid();part uuid;r uuid;result jsonb;denied boolean;n uuid;rev integer;
begin
 begin
 insert into auth.users(id) values(admin_user),(manager_user),(school_user),(pending_user);
 insert into public.institutions(id,name,slug) values(tenant,'Avisos','notify-'||tenant),(other_tenant,'Outro','notify-'||other_tenant);
 insert into public.institution_memberships(institution_id,user_id,role,status) values(tenant,admin_user,'admin','approved'),(tenant,manager_user,'manager','approved'),(tenant,pending_user,'manager','pending');
 insert into public.schools(id,institution_id,name) values(school,tenant,'Escola dos avisos');
 insert into public.events(id,institution_id,name,status) values(ev,tenant,'Evento dos avisos','open');
 insert into public.event_modalities(id,institution_id,event_id,name,classification) values(sport,tenant,ev,'Atletismo','individual');
 insert into public.event_categories(id,institution_id,event_id,modality_id,name,participation) values(cat,tenant,ev,sport,'Livre','individual');
 insert into public.people(id,institution_id,full_name,birth_date,cpf,gender) values(person,tenant,'Atleta','2010-01-01','52998224725','Feminino'),(guardian,tenant,'Responsável','1990-01-01','11144477735','Feminino');
 insert into public.school_people(institution_id,school_id,person_id,role,status,user_id) values(tenant,school,person,'athlete','approved',null),(tenant,school,guardian,'responsible','approved',school_user);
 perform set_config('request.jwt.claim.sub',school_user::text,true);execute 'set local role authenticated';
 result:=public.siep_save_participation(ev,school,person,array[cat],'{}',true);part:=(result->>'id')::uuid;
 result:=public.siep_save_registration(ev,school,cat,null,jsonb_build_array(jsonb_build_object('participation_id',part,'slot_number',1)),'[]');r:=(result->>'id')::uuid;
 result:=public.siep_transition_registration(r,1,'submitted','Primeiro envio');
 execute 'reset role';
 if (select count(*) from public.notifications where institution_id=tenant and kind='registration_submitted')<>2 then raise exception 'Destinatários da Secretaria incorretos';end if;
 if exists(select 1 from public.notifications where recipient_user_id=pending_user) then raise exception 'Pendente recebeu aviso';end if;
 select id into n from public.notifications where recipient_user_id=admin_user and institution_id=tenant limit 1;
 perform set_config('request.jwt.claim.sub',school_user::text,true);execute 'set local role authenticated';
 denied:=false;begin perform public.siep_mark_notification_read(n);exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Escola marcou aviso alheio';end if;
 denied:=false;begin perform public.siep_notification_center(other_tenant);exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Consulta atravessou instituição';end if;
 execute 'reset role';perform set_config('request.jwt.claim.sub',admin_user::text,true);execute 'set local role authenticated';
 result:=public.siep_notification_center(tenant);
 if (result->>'unread')::int<>1 or result#>>'{rows,0,payload,school_id}'<>school::text or result#>>'{rows,0,payload,event_name}'<>'Evento dos avisos' then raise exception 'Centro não retornou contexto: %',result;end if;
 perform public.siep_mark_notification_read(n);perform public.siep_mark_notification_read(n);
 result:=public.siep_notification_center(tenant);if (result->>'unread')::int<>0 then raise exception 'Leitura não foi idempotente';end if;
 result:=public.siep_transition_registration(r,2,'correction_requested','Corrigir documento',now()+interval '12 hours');
 execute 'reset role';perform set_config('request.jwt.claim.sub',school_user::text,true);execute 'set local role authenticated';
 result:=public.siep_notification_center(tenant);result:=public.siep_notification_center(tenant);
 execute 'reset role';
 if (select count(*) from public.notifications where institution_id=tenant and recipient_user_id=school_user and kind='correction_deadline')<>1 then raise exception 'Lembrete duplicado ou ausente';end if;
 if exists(select 1 from public.notifications where institution_id=tenant and kind='correction_deadline' and recipient_user_id<>school_user) then raise exception 'Lembrete enviado a quem não é responsável';end if;
 perform set_config('request.jwt.claim.sub',school_user::text,true);execute 'set local role authenticated';
 result:=public.siep_transition_registration(r,3,'submitted','Corrigido');execute 'reset role';
 if not exists(select 1 from public.notifications where recipient_user_id=admin_user and payload->>'resubmitted'='true') then raise exception 'Reenvio não avisou Secretaria';end if;
 if (select count(*) from public.notifications where institution_id=tenant and kind='registration_submitted')<>4 then raise exception 'Reenvio duplicado';end if;
 perform set_config('request.jwt.claim.sub',admin_user::text,true);execute 'set local role authenticated';
 result:=public.siep_transition_registration(r,4,'approved','Conferido');execute 'reset role';
 if not exists(select 1 from public.notifications where recipient_user_id=school_user and payload->>'status'='approved') then raise exception 'Escola não recebeu aprovação';end if;
 perform set_config('request.jwt.claim.sub',school_user::text,true);execute 'set local role authenticated';result:=public.siep_notification_center(tenant);execute 'reset role';
 if (select count(*) from public.notifications where institution_id=tenant and kind='correction_deadline')<>1 then raise exception 'Inscrição aprovada gerou lembrete';end if;
 update public.registrations set status='correction_requested',revision=revision+1,correction_deadline=now()-interval '1 minute' where id=r;
 perform set_config('request.jwt.claim.sub',school_user::text,true);execute 'set local role authenticated';result:=public.siep_notification_center(tenant);execute 'reset role';
 update public.registrations set correction_deadline=now()+interval '48 hours' where id=r;
 execute 'set local role authenticated';result:=public.siep_notification_center(tenant);execute 'reset role';
 if (select count(*) from public.notifications where institution_id=tenant and kind='correction_deadline')<>1 then raise exception 'Prazo fora da janela gerou lembrete';end if;
 insert into public.notifications(institution_id,recipient_user_id,kind,payload,deduplication_key) select tenant,admin_user,'test','{}','test-limit-'||g from generate_series(1,12) g;
 perform set_config('request.jwt.claim.sub',admin_user::text,true);execute 'set local role authenticated';result:=public.siep_notification_center(tenant);execute 'reset role';
 if jsonb_array_length(result->'rows')<>10 or (result->>'unread')::int<=10 then raise exception 'Limite confundido com total não lido';end if;
 update public.school_people set status='closed' where user_id=school_user and institution_id=tenant;
 perform set_config('request.jwt.claim.sub',school_user::text,true);execute 'set local role authenticated';denied:=false;begin perform public.siep_notification_center(tenant);exception when insufficient_privilege then denied:=true;end;execute 'reset role';if not denied then raise exception 'Acesso revogado consultou sino';end if;
 if has_function_privilege('anon','public.siep_notification_center(uuid)','execute') or has_function_privilege('authenticated','siep_private.notify_submission()','execute') then raise exception 'Permissão de função incorreta';end if;
 raise exception 'rollback_notification_center' using errcode='ZX001';
 exception when sqlstate 'ZX001' then null;
 end;
end $$;
